-- Swastha unified Behavioural Therapy Skills Assessment, based on Behavioural Therapy(1).pdf
-- Uses current six-part custom assessment layout, assignment and parent submit / teacher review workflow.
-- Preserves 60 scored items, baseline, ABC, sensory, strengths, summary, plans and oversight.
INSERT INTO public.custom_assessment_templates (title,description,level,structure,status,created_by,scoring_guide)
SELECT 'Behavioural Therapy — Skills Assessment','Informal non-standardized assessment based on Behavioural Therapy(1).pdf, 7 pages. Original six-part structure: 60 rating items across nine domains plus client details, sensory observations, four baseline records, five ABC observation rows, possible-function hypothesis, strengths, domain priorities, three intervention plans and review details. Score 0=Not demonstrated; 1=Full assistance; 2=Partial assistance; 3=Independent. The existing form offers NA rather than separate N/O and N/A: record the distinction in observation remarks. NA excluded from applicable maximum. No diagnostic or severity cutoffs. Qualified assessor supervision and child assent required.','all','[{"id":"s_BT2_01","title":"01 — Client details and attending skills","categories":[{"id":"c_BT2_CLIENT","title":"Client information","questions":[{"id":"q_BT2_CLIENT_01","text":"Name / client ID","text_ml":"","response_type":"written"},{"id":"q_BT2_CLIENT_02","text":"Age / date of birth","text_ml":"","response_type":"written"},{"id":"q_BT2_CLIENT_03","text":"Parent / caregiver","text_ml":"","response_type":"written"},{"id":"q_BT2_CLIENT_04","text":"Assessment date / setting","text_ml":"","response_type":"written"},{"id":"q_BT2_CLIENT_05","text":"Diagnosis (if documented)","text_ml":"","response_type":"written"},{"id":"q_BT2_CLIENT_06","text":"Presenting concerns","text_ml":"","response_type":"written"},{"id":"q_BT2_CLIENT_07","text":"Assessor / supervisor","text_ml":"","response_type":"written"}]},{"id":"c_BT2_A","title":"A. Attention and attending","questions":[{"id":"q_BT2_A_01","text":"Responds to name","text_ml":"","response_type":"rating"},{"id":"q_BT2_A_02","text":"Joint attention","text_ml":"","response_type":"rating"},{"id":"q_BT2_A_03","text":"Engages in activity","text_ml":"","response_type":"rating"},{"id":"q_BT2_A_04","text":"Attention span (record duration)","text_ml":"","response_type":"rating"},{"id":"q_BT2_A_05","text":"Task completion","t