FROM public.user_roles ur JOIN auth.users au ON au.id=ur.user_id
WHERE ur.role IN ('owner','teacher')
AND NOT EXISTS(SELECT 1 FROM public.custom_assessment_templates t WHERE t.title='Behavioural Therapy — Skills Assessment')
ORDER BY CASE WHEN ur.role='owner' THEN 0 ELSE 1 END,ur.created_at LIMIT 1;